#[target_feature(enable = "avx512f,avx2")]
fn test_x86_avx512f_mm512_min_epi32_vs_narrow_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("avx2")) {
            return Ok(Verdict::Skipped("avx2 not present"));
        }
    unsafe {
        let a_wide = create__m512i_from_i32_array([1i32, 2i32, 3i32, 4i32, 5i32, 6i32, 7i32, 8i32, 9i32, 10i32, 11i32, 12i32, 13i32, 14i32, 15i32, 16i32]);
        let a_narrow = create__m256i_from_i32_array([1i32, 2i32, 3i32, 4i32, 5i32, 6i32, 7i32, 8i32]);
        let b_wide = create__m512i_from_i32_array([17i32, 18i32, 19i32, 20i32, 21i32, 22i32, 23i32, 24i32, 25i32, 26i32, 27i32, 28i32, 29i32, 30i32, 31i32, 32i32]);
        let b_narrow = create__m256i_from_i32_array([17i32, 18i32, 19i32, 20i32, 21i32, 22i32, 23i32, 24i32]);
        let wide = unpack__m512i_to_i32_array(_mm512_min_epi32(a_wide, b_wide));
        let narrow = unpack__m256i_to_i32_array(_mm256_min_epi32(a_narrow, b_narrow));
        check_array_equality(&wide[..8], &narrow).map_err(|e| crate::cpu::with_call(e, "_mm512_min_epi32(a_wide, b_wide) vs _mm256_min_epi32(a_narrow, b_narrow)"))?;
        Ok(Verdict::Checked)
    }
}

pub(super) fn test_x86_avx512f_mm512_min_epi32_vs_narrow() -> Result<Verdict, String> {
    unsafe { test_x86_avx512f_mm512_min_epi32_vs_narrow_impl() }
}

#[target_feature(enable = "avx512f")]
fn test_x86_avx512f_mm512_min_epi32_prop_commutative_impl() -> Result<Verdict, String> {
    unsafe {
        let a = create__m512i_from_i32_array([1i32, 2i32, 3i32, 4i32, 5i32, 6i32, 7i32, 8i32, 9i32, 10i32, 11i32, 12i32, 13i32, 14i32, 15i32, 16i32]);
        let b = create__m512i_from_i32_array([17i32, 18i32, 19i32, 20i32, 21i32, 22i32, 23i32, 24i32, 25i32, 26i32, 27i32, 28i32, 29i32, 30i32, 31i32, 32i32]);
        let lhs = unpack__m512i_to_i32_array(_mm512_min_epi32(a, b));
        let rhs = unpack__m512i_to_i32_array(_mm512_min_epi32(b, a));
        check_array_equality(&lhs, &rhs).map_err(|e| crate::cpu::with_call(e, "_mm512_min_epi32(a, b) vs _mm512_min_epi32(b, a)"))?;
        Ok(Verdict::Checked)
    }
}

