#[target_feature(enable = "avx512f,avx2")]
fn test_x86_avx512f_mm512_min_epu32_vs_narrow_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("avx2")) {
            return Ok(Verdict::Skipped("avx2 not present"));
        }
    unsafe {
        let a_wide = create__m512i_from_u32_array([1u32, 2u32, 3u32, 4u32, 5u32, 6u32, 7u32, 8u32, 9u32, 10u32, 11u32, 12u32, 13u32, 14u32, 15u32, 16u32]);
        let a_narrow = create__m256i_from_u32_array([1u32, 2u32, 3u32, 4u32, 5u32, 6u32, 7u32, 8u32]);
        let b_wide = create__m512i_from_u32_array([17u32, 18u32, 19u32, 20u32, 21u32, 22u32, 23u32, 24u32, 25u32, 26u32, 27u32, 28u32, 29u32, 30u32, 31u32, 32u32]);
        let b_narrow = create__m256i_from_u32_array([17u32, 18u32, 19u32, 20u32, 21u32, 22u32, 23u32, 24u32]);
        let wide = unpack__m512i_to_u32_array(_mm512_min_epu32(a_wide, b_wide));
        let narrow = unpack__m256i_to_u32_array(_mm256_min_epu32(a_narrow, b_narrow));
        check_array_equality(&wide[..8], &narrow).map_err(|e| crate::cpu::with_call(e, "_mm512_min_epu32(a_wide, b_wide) vs _mm256_min_epu32(a_narrow, b_narrow)"))?;
        Ok(Verdict::Checked)
    }
}

