#[target_feature(enable = "avx512f")]
fn test_x86_avx512f_mm256_maskz_min_epu64_vs_unmasked_impl() -> Result<Verdict, String> {
    unsafe {
        let a = create__m256i_from_i32_array([1, 2, 3, 4, 5, 6, 7, 8]);
        let b = create__m256i_from_i32_array([9, 10, 11, 12, 13, 14, 15, 16]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m256i_to_u64_array(_mm256_maskz_min_epu64(k, a, b));
        let plain = unpack__m256i_to_u64_array(_mm256_min_epu64(a, b));
        let expected: [u64; 4] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { 0 });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm256_maskz_min_epu64(k, a, b) vs _mm256_min_epu64(a, b)"))?;
        Ok(Verdict::Checked)
    }
}

