fn test_x86_avx512f_mm_maskz_min_epu64_vs_unmasked_impl() -> Result<Verdict, String> {
    unsafe {
        let a = create__m128i_from_i32_array([1, 2, 3, 4]);
        let b = create__m128i_from_i32_array([5, 6, 7, 8]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m128i_to_u64_array(_mm_maskz_min_epu64(k, a, b));
        let plain = unpack__m128i_to_u64_array(_mm_min_epu64(a, b));
        let expected: [u64; 2] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { 0 });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm_maskz_min_epu64(k, a, b) vs _mm_min_epu64(a, b)"))?;
        Ok(Verdict::Checked)
    }
}

